  { id: 'hiring', title: 'Interview', start: at(28, 10, 30), end: at(28, 11, 30), tone: 'warning' },
  {
    id: 'lunch',
    title: 'Lunch with partners',
    start: at(28, 11),
    end: at(28, 13),
    tone: 'success',
  },
  { id: 'planning', title: 'Sprint planning', start: at(30, 13), end: at(30, 15) },
  // Fixed in place: not moved or resized.
  {
